// init height for non-collapsed code snippets so animation will be show
// their first collapse
const nonCollapsedSnippets = document.querySelectorAll(
  ".frame:not(.collapsed) .code-snippet-wrapper",
);

for (const snippet of nonCollapsedSnippets) {
  snippet.style.height = `${snippet.scrollHeight}px`;
}

function toggleTracebackView() {
  const tracebackArea = document.getElementById("traceback_area");
  const tracebackControls = document.querySelector(".traceback-controls");
  const interactiveView = document.querySelector(".interactive-view");
  const plaintextView = document.querySelector(".plaintext-view");

  if (tracebackArea.style.display === "block") {
    tracebackArea.style.display = "none";
    tracebackControls.querySelector("#view_toggle").textContent = "Plaintext view";
    interactiveView.style.display = "block";
    plaintextView.style.display = "none";
  } else {
    tracebackArea.style.display = "block";
    tracebackControls.querySelector("#view_toggle").textContent = "Interactive view";
    interactiveView.style.display = "none";
    plaintextView.style.display = "block";
  }
}

function copyTraceback() {
  const tracebackArea = document.getElementById("traceback_area");
  if (tracebackArea) {
    navigator.clipboard.writeText(tracebackArea.value).then(
      function() {
        console.log("Traceback copied to clipboard");
      },
      function(err) {
        console.error("Unable to copy traceback: ", err);
      }
    );
  }
}
